package Distinct_Subsequences_II;

import java.util.Arrays;

public class Solution4 {
	int MOD = 1_000_000_007;
	public int distinctSubseqII(String s) {
		int n = s.length();
		
		int[] dp = new int[n+1];
		dp[0] = 1;
		
		int[] prevIndex = new int[n+1];
		
		int lastSeen[] = new int[26];
		Arrays.fill(lastSeen, -1);
		
		for(int i=1;i<=n;i++) {
			int idx = s.charAt(i-1) - 'a';
			prevIndex[i] = lastSeen[idx];
			lastSeen[idx] = i;
		}
		
		for(int i=1;i<=n;i++) {
			int total = (2 * dp[i-1]) % MOD;
			
			if(prevIndex[i] != -1) {
				int duplicate = dp[prevIndex[i] - 1] % MOD;
				total = (total - duplicate + MOD) % MOD;
			}
			
			dp[i] = total;
		}
		
		return (dp[n] - 1 + MOD) % MOD;
    }

    public static void main(String[] args) {
    	String s = "";
    	
    	Solution4 sol4 = new Solution4();
    	System.out.println("Output: " + sol4.distinctSubseqII(s));
	}
}